import{n as e}from"./axiosConfig-DAsVegoh.js";var t={getPermissions:async()=>{try{return(await e.get(`/v1/society/permissions`)).data}catch(e){throw e}},create:async t=>{try{return(await e.post(`/v1/society/roles`,t)).data}catch(e){throw e}},list:async(t={})=>{try{return(await e.get(`/v1/society/roles`,{params:t})).data}catch(e){throw e}},getRolesDropdown:async()=>{try{return(await e.get(`/v1/society/roles`,{params:{limit:100}})).data}catch(e){throw e}},getById:async t=>{try{return(await e.get(`/v1/society/roles/${t}`)).data}catch(e){throw e}},update:async(t,n)=>{try{return(await e.put(`/v1/society/roles/${t}`,n)).data}catch(e){throw e}},delete:async t=>{try{return(await e.delete(`/v1/society/roles/${t}`)).data}catch(e){throw e}}};export{t};